"""Render evaluation results as Markdown: pass rates, every failure, and the drafts."""

from collections.abc import Mapping, Sequence
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from content_agent.evaluate import CaseResult, EvalRun


def render_report(run: "EvalRun", meta: Mapping[str, str]) -> str:
    """Build the full report. Failures are always listed, never summarized away."""
    results = run.results
    lines = [
        "# Evaluation results",
        "",
        "Generated by `python -m content_agent.evaluate`. Do not edit by hand.",
        "",
        *(f"- **{key}:** {value}" for key, value in meta.items()),
        "",
        *_incomplete_warning(run.stopped_early),
        f"**Overall pass rate (every check passed): "
        f"{_rate(sum(r.passed for r in results), len(results))}**",
        "",
        *_check_table(results),
        "",
        *_kind_table(results),
        "",
        *_failures(results),
        "",
        *_case_table(results),
        "",
        *_drafts(results),
    ]
    return "\n".join(lines) + "\n"


def _incomplete_warning(stopped_early: str) -> list[str]:
    if not stopped_early:
        return []
    return [
        f"> **Incomplete run.** Stopped early: {stopped_early}. The numbers below cover only "
        "the cases that ran and are not comparable with a complete run.",
        "",
    ]


def _rate(passed: int, total: int) -> str:
    return f"{passed}/{total} ({passed / total:.0%})" if total else "n/a"


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def _check_table(results: Sequence["CaseResult"]) -> list[str]:
    totals: dict[str, list[int]] = {}
    for result in results:
        for name, ok in result.checks.items():
            passed_total = totals.setdefault(name, [0, 0])
            passed_total[0] += ok
            passed_total[1] += 1
    rows = [f"| {name} | {_rate(p, t)} |" for name, (p, t) in totals.items()]
    return ["## Pass rate per check", "", "| Check | Passed |", "|---|---|", *rows]


def _kind_table(results: Sequence["CaseResult"]) -> list[str]:
    kinds = dict.fromkeys(r.case.kind for r in results)
    rows = []
    for kind in kinds:
        of_kind = [r for r in results if r.case.kind == kind]
        rows.append(f"| {kind} | {_rate(sum(r.passed for r in of_kind), len(of_kind))} |")
    return ["## Pass rate per case kind", "", "| Kind | Passed |", "|---|---|", *rows]


def _failures(results: Sequence["CaseResult"]) -> list[str]:
    failed = [r for r in results if not r.passed]
    lines = ["## Failures", ""]
    if not failed:
        return [*lines, "None."]
    for r in failed:
        failing = ", ".join(name for name, ok in r.checks.items() if not ok)
        expected = " or ".join(status.value for status in r.case.expect)
        lines.append(
            f"- `{r.case.id}` ({r.case.kind}): failed {failing}. Expected {expected}, "
            f"got {r.result.status.value}."
            + (f" Flags: {'; '.join(r.result.flags)}." if r.result.flags else "")
            + (f" Error: {r.result.error}" if r.result.error else "")
        )
    return lines


def _case_table(results: Sequence["CaseResult"]) -> list[str]:
    lines = [
        "## Every case",
        "",
        "| Case | Kind | Expected | Got | Draft attempts | HTTP requests | Flags / error | Pass |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for r in results:
        detail = _cell("; ".join(r.result.flags) or r.result.error)
        expected = " or ".join(status.value for status in r.case.expect)
        lines.append(
            f"| `{r.case.id}` | {r.case.kind} | {expected} | {r.result.status.value} | "
            f"{r.llm_calls} | {r.requests} | {detail} | {'yes' if r.passed else '**no**'} |"
        )
    return lines


def _drafts(results: Sequence["CaseResult"]) -> list[str]:
    lines = ["## Drafts", "", "Full text of every draft, for review by hand.", ""]
    for r in results:
        if not (draft := r.result.draft):
            continue
        slides = "\n".join(f"{n}. {slide}" for n, slide in enumerate(draft.slides, 1))
        lines += [
            f"<details><summary><code>{r.case.id}</code>: {r.case.topic}</summary>",
            "",
            f"**Caption**\n\n{draft.caption}\n",
            f"**Carousel**\n\n{slides}\n",
            f"**Script**\n\n{draft.script}\n",
            "</details>",
            "",
        ]
    return lines
